"use strict";

class Charset {
  constructor(...items) {
    this._set = new Set();
    for (const item of items) {
      this._add(item);
    }
  }

  union(...items) {
    const next = new Charset();
    next._set = new Set(this._set);
    for (const item of items) {
      next._add(item);
    }
    return next;
  }

  subtract(...items) {
    const next = new Charset();
    next._set = new Set(this._set);
    for (const item of items) {
      next._remove(item);
    }
    return next;
  }

  toString() {
    const codes = Array.from(this._set).sort((a, b) => a - b);
    const parts = codes.map(code => Charset._escapeForCharClass(code));
    return `[${parts.join("")}]`;
  }

  _add(item) {
    if (Array.isArray(item) && item.length === 2) {
      const start = item[0] | 0;
      const end = item[1] | 0;
      for (let c = start; c <= end; c++) this._set.add(c);
      return;
    }
    if (typeof item === "number") {
      this._set.add(item | 0);
      return;
    }
    if (typeof item === "string") {
      for (const ch of item) this._set.add(ch.codePointAt(0));
      return;
    }
  }

  _remove(item) {
    if (Array.isArray(item) && item.length === 2) {
      const start = item[0] | 0;
      const end = item[1] | 0;
      for (let c = start; c <= end; c++) this._set.delete(c);
      return;
    }
    if (typeof item === "number") {
      this._set.delete(item | 0);
      return;
    }
    if (typeof item === "string") {
      for (const ch of item) this._set.delete(ch.codePointAt(0));
      return;
    }
  }

  static _escapeForCharClass(codePoint) {
    if (codePoint <= 0xff) {
      return `\\x${codePoint.toString(16).padStart(2, "0")}`;
    }
    return `\\u${codePoint.toString(16).padStart(4, "0")}`;
  }
}

module.exports = { Charset };

